# -*- coding: utf-8 -*-
# MT2009_PLUS_GROWTH_PET_V1 - System Zwierzat Domowych in the client's data (the data part; the window is root python).
# One source: <repo>/tools/pety/pety_items.json (generated by tools/pety/gen_pety_sql.py from tools/pety/pety_data.py,
# the same records the server's linux-port/docker/mariadb/playerbot/pety.sql writes - never edit the json by hand).
#
#   gamedata/item_proto (dbdata)   one record a json item: vnum, name and locale name = the Polish name (cp1250,
#                                  < 33 bytes), type, subtype, stack, antiflags, flags, limittype0/limitvalue0 in the
#                                  first limit slot, values[6]; buy price (offset 98) = the json's "gold", sell price
#                                  (offset 106) = "shop_buy_price" (the server's columns of the same names - as
#                                  ../yohara's yitem_record); weight 0, size 1, no wear/immune/apply/socket/refine
#   gamedata/item_list.txt         <vnum>\tETC\t<icon>
#   locale/pl/itemdesc.txt (dbdata) <vnum>\t<name>\t<description>
#   gamedata/mob_proto             the 42 pet mobs (young / heroic / champion of the 14 species): copies of 34001's
#                                  record (the ItemShop pet the server clones too) with the vnum, the name (ASCII, as the
#                                  server's), the locale name (Polish, cp1250 < 25 bytes) and the model folder set
#   gamedata/npclist.txt           <vnum>\t<model> for the 42 mobs and 0\t<model>\t<folder> for a model whose .msm is in
#                                  another model's folder (GF 26.1.11's shared/common/npclist.txt rows)
# The old New Pet system's records go: 55101-55118 (Eliksir Witalnosci / Walki / Mocy) - their item_proto records,
# item_list and itemdesc lines are removed; its other 55xxx records (55001-55036, 55401-55411) are overwritten by the
# json's records of the same vnums. A line or record that is there with other content is rewritten (these vnums are
# the pet system's); idempotent: a second run changes nothing.
#
# By hand, on plain copies (the m2pack-lzo image for MCOZ):
#   docker run --rm -v /opt/metin2:/opt/metin2 m2pack-lzo python3 \
#     <repo>/client-patches/client-2.0.30/tools/pety/patch_pety_client.py <item_proto|item_list.txt|itemdesc.txt|mob_proto|npclist.txt> ... [--check]
import io
import json
import os
import struct
import sys
import unicodedata

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, '/opt/metin2/cache/tcm/tz')
sys.path.insert(0, os.path.join(HERE, '..', 'monstercard'))
sys.path.insert(0, os.path.join(HERE, '..', 'shipdefense'))
import patch_monstercard_client as base  # noqa: E402
import patch_shipdefense_client as sd  # noqa: E402

REPO = os.path.normpath(os.path.join(HERE, '..', '..', '..', '..'))
JSON = os.environ.get('PETY_JSON') or os.path.join(REPO, 'tools', 'pety', 'pety_items.json')
OLD_REMOVE = tuple(range(55101, 55119))     # the old New Pet system's elixirs
MOB_TEMPLATE = 34001                        # phoenix1 - an ItemShop pet (NPC, level 1); the server clones it too

# species -> (category, model folder, (young, heroic, champion) model names) - GF 26.1.11 npclist + d:/ymir work
# (the exe looks for d:/ymir work/<category>/<folder>/<model>.msm, npc_pet first for 34028-34099, npc2 first above)
MODELS = (
    ('npc_pet', 'monkey_young1', ('monkey_young1', 'monkey_young2', 'monkey_young3')),
    ('npc_pet', 'spider_redpoison_young1', ('spider_redpoison_young1', 'spider_redpoison_young2',
                                            'spider_redpoison_young3')),
    ('npc_pet', 'yamachun_young1', ('yamachun_young1', 'yamachun_young2', 'yamachun_young3')),
    ('npc_pet', 'hanma_young1', ('hanma_young1', 'hanma_young2', 'hanma_young3')),
    ('npc_pet', 'blue_dragon_young1', ('blue_dragon_young1', 'blue_dragon_young2', 'blue_dragon_young3')),
    ('npc_pet', 'red_dragon_young1', ('red_dragon_young1', 'red_dragon_young2', 'red_dragon_young3')),
    ('npc2', 'pwahuang1', ('pwahuang1_3', 'pwahuang1_4', 'pwahuang1_5')),
    ('npc2', 'redthief2_officer_young1', ('redthief2_officer_young3', 'redthief2_officer_young4',
                                          'redthief2_officer_young5')),
    ('npc_pet', 'luck_sheep_young1', ('luck_sheep_young1', 'luck_sheep_young2', 'luck_sheep_young3')),
    ('npc_pet', 'defensewave_hydra_pet', ('defensewave_hydra_pet_1', 'defensewave_hydra_pet_2',
                                          'defensewave_hydra_pet_3')),
    ('npc_pet', 'pve_dragon_young', ('pve_dragon_young_1', 'pve_dragon_young_2', 'pve_dragon_young_3')),
    ('npc_pet', 'whitedragon_pet', ('whitedragon_pet_1', 'whitedragon_pet_2', 'whitedragon_pet_3')),
    ('npc_pet', 'smhgate_young', ('smhgate_young_1', 'smhgate_young_2', 'smhgate_young_3')),
    ('npc_pet', 'greedy_room_young', ('greedy_room_young', 'greedy_room_young_2', 'greedy_room_young_3')),
)
# the GF npclist's own "0 luck_sheep_young1 luck_sheep_young1" row (the model in its own folder) - kept as GF has it
SELF_SRC = ('luck_sheep_young1',)

_data = None


def data():
    global _data
    if _data is None:
        with io.open(JSON, encoding='utf-8') as f:
            _data = json.load(f)
        assert len(_data['mobs']) == 42 and len(_data['skills']) == 23, JSON
        assert len(_data['species']) == len(MODELS), 'species / MODELS'
    return _data


def models():
    """vnum -> (category, folder, model) of the 42 pet mobs, from the json's species and MODELS (same order)"""
    out = {}
    for sp, (cat, folder, names) in zip(sorted(data()['species'], key=lambda s: s['idx']), MODELS):
        for v, n in zip(sp['mobs'], names):
            out[v] = (cat, folder, n)
    assert set(out) == set(m['vnum'] for m in data()['mobs']), 'json mobs / species'
    return out


def items():
    return data()['items']


def ascii_name(text):
    t = unicodedata.normalize('NFKD', text.replace(u'ł', 'l').replace(u'Ł', 'L'))
    return ''.join(c for c in t if ord(c) < 128).replace("'", '')


def item_record(it):
    for k in ('name', 'desc'):
        assert '\t' not in it[k] and '\n' not in it[k] and '\r' not in it[k], (it['vnum'], k)
    assert len(it['name'].encode('cp1250')) < 33, it['name']
    r = bytearray(base.RECORD)
    struct.pack_into('<II', r, 0, it['vnum'], 0)
    r[8:41] = base.fixed(it['name'], 33)
    r[41:74] = base.fixed(it['name'], 33)
    struct.pack_into('<BBBB', r, 74, it['type'], it['subtype'], 0, 1)                  # weight 0, size 1
    struct.pack_into('<IIIII', r, 78, it['stack'], it['antiflag'], it['flag'], 0, 0)   # stack, anti, flags, wear, immune
    struct.pack_into('<qq', r, 98, it['gold'], it['shop_buy_price'])                  # buy, sell
    struct.pack_into('<BiBi', r, 114, it['limittype0'], it['limitvalue0'], 0, 0)
    assert len(it['values']) == 6, it['vnum']
    struct.pack_into('<6i', r, 139, *it['values'])
    return bytes(r)


def item_proto(b):
    import m2pack
    assert b[:4] == b'MIPX'
    ver, stride, cnt, size = struct.unpack_from('<IIII', b, 4)
    assert stride == base.RECORD, stride
    raw = m2pack.mcoz_decode(b[20:], base.ITEM_KEY)
    recs = dict((struct.unpack_from('<I', raw, i * base.RECORD)[0], raw[i * base.RECORD:(i + 1) * base.RECORD])
                for i in range(cnt))
    changed = 0
    for v in OLD_REMOVE:
        if v in recs:
            del recs[v]
            changed += 1
    for it in items():
        r = item_record(it)
        if recs.get(it['vnum']) != r:
            recs[it['vnum']] = r
            changed += 1
    if not changed:
        return b, 0
    out = b''.join(recs[v] for v in sorted(recs))
    blob = m2pack.mcoz_encode(out, base.ITEM_KEY)
    return b'MIPX' + struct.pack('<IIII', ver, stride, len(recs), len(blob)) + blob, changed


def drop_rows(b, keys):
    """removes every line whose first column is one of keys; keeps the file's line ends"""
    text = b.decode('cp1250')
    nl = '\r\n' if '\r\n' in text else '\n'
    lines = text.split(nl)
    keep = [l for l in lines if l.split('\t')[0].strip() not in keys]
    if len(keep) == len(lines):
        return b, 0
    return nl.join(keep).encode('cp1250'), len(lines) - len(keep)


def list_rows():
    return [u'%d\tETC\t%s' % (it['vnum'], it['icon']) for it in items()]


def desc_rows():
    return [u'%d\t%s\t%s' % (it['vnum'], it['name'], it['desc']) for it in items()]


def _with_removal(b, rows):
    b, n1 = drop_rows(b, set(str(v) for v in OLD_REMOVE))
    b, n2 = base.set_rows(b, rows)
    return b, n1 + n2


def item_list(b):
    return _with_removal(b, list_rows())


def itemdesc(b):
    return _with_removal(b, desc_rows())


def mob_record(tmpl, vnum, name, folder):
    r = bytearray(tmpl)
    assert len(name.encode('cp1250')) < 25, name
    struct.pack_into('<I', r, 0, vnum)
    r[4:29] = sd.fixed(ascii_name(name)[:24], 25)
    r[29:54] = sd.fixed(name, 25)
    r[140:204] = sd.fixed(folder, 64)
    return bytes(r)


def mob_proto(b):
    import m2pack
    magic, cnt, esize = struct.unpack_from('<4sII', b, 0)
    assert magic == b'MMPT', magic
    R = sd.MOB_RECORD
    raw = m2pack.mcoz_decode(b[12:12 + esize], sd.MOB_KEY)
    assert len(raw) == cnt * R, (len(raw), cnt)
    recs = dict((struct.unpack_from('<I', raw, i * R)[0], raw[i * R:(i + 1) * R]) for i in range(cnt))
    assert MOB_TEMPLATE in recs, 'mob_proto: no %d (the template)' % MOB_TEMPLATE
    mod = models()
    changed = 0
    for m in data()['mobs']:
        r = mob_record(recs[MOB_TEMPLATE], m['vnum'], m['name'], mod[m['vnum']][2])
        if recs.get(m['vnum']) != r:
            recs[m['vnum']] = r
            changed += 1
    if not changed:
        return b, 0
    out = b''.join(recs[v] for v in sorted(recs))
    blob = m2pack.mcoz_encode(out, sd.MOB_KEY)
    return struct.pack('<4sII', b'MMPT', len(recs), len(blob)) + blob, changed


def npclist_rows():
    """(key, row): vnum rows and the 0-rows (model -> folder) the 42 mobs need"""
    rows = []
    mod = models()
    for v in sorted(mod):
        rows.append((str(v), u'%d\t%s' % (v, mod[v][2])))
    srcs = {}
    for cat, folder, model in mod.values():
        if model != folder or model in SELF_SRC:
            srcs[model] = folder
    for model in sorted(srcs):
        rows.append(('0:' + model.lower(), u'0\t%s\t%s' % (model, srcs[model])))
    return rows


def _npc_key(line):
    t = line.split('\t')
    k = t[0].strip()
    if k == '0' and len(t) > 1:
        return '0:' + t[1].strip().lower()
    return k


def npclist(b):
    text = b.decode('cp1250')
    nl = '\r\n' if '\r\n' in text else '\n'
    lines = text.split(nl)
    tail = bool(lines) and lines[-1] == ''
    if tail:
        lines.pop()
    changed = 0
    for key, row in npclist_rows():
        hits = [i for i, l in enumerate(lines) if _npc_key(l) == key]
        if hits:
            for i in hits:
                if lines[i].split() != row.split():
                    lines[i] = row
                    changed += 1
        else:
            lines.append(row)
            changed += 1
    if not changed:
        return b, 0
    if tail:
        lines.append('')
    return nl.join(lines).encode('cp1250'), changed


# the pack builder's jobs: an entry's name -> fn(bytes) -> (new bytes, changes)
JOBS = {'gamedata/item_list.txt': item_list, 'gamedata/mob_proto': mob_proto, 'gamedata/npclist.txt': npclist,
        'gamedata/item_proto': item_proto, 'locale/pl/itemdesc.txt': itemdesc}
PACK_OF = {'gamedata/item_list.txt': 'gamedata', 'gamedata/mob_proto': 'gamedata', 'gamedata/npclist.txt': 'gamedata',
           'gamedata/item_proto': 'dbdata', 'locale/pl/itemdesc.txt': 'dbdata'}
BY_FILE = dict((os.path.basename(k), f) for k, f in JOBS.items())


def pet_skill_txt():
    """locale/pl/pet_skill.txt: id, name, icon, PASSIVE|AUTO, description, cooldown seconds (tabs, CRLF, cp1250) - the
    exe's CPythonSkill::RegisterPetSkillTable (6 columns; the icon is d:/ymir work/ui/skill/pet/<icon>.sub)"""
    sk = data()['skills']
    lines = []
    for i in range(1, 24):
        s = sk[str(i)]
        assert s['kind'] in ('PASSIVE', 'AUTO'), i
        for k in ('name', 'icon', 'desc'):
            assert s[k] and '\t' not in s[k] and '\n' not in s[k], (i, k)
        lines.append(u'%d\t%s\t%s\t%s\t%s\t%d' % (i, s['name'], s['icon'], s['kind'], s['desc'], int(s['cooldown'])))
    return (u'\r\n'.join(lines) + u'\r\n').encode('cp1250')


def main():
    args = [a for a in sys.argv[1:] if a != '--check']
    check = '--check' in sys.argv
    if not args:
        raise SystemExit('usage: patch_pety_client.py <item_proto|item_list.txt|itemdesc.txt|mob_proto|npclist.txt> ... '
                         '[--check]')
    for path in args:
        fn = BY_FILE[os.path.basename(path)]
        b = open(path, 'rb').read()
        nb, n = fn(b)
        if n and not check:
            open(path, 'wb').write(nb)
        print('%s: %d change(s)%s' % (os.path.basename(path), n, ' (check only)' if check else ''))


if __name__ == '__main__':
    main()
